"""Self-contained, script-free reports; repository text is escaped."""
from html import escape


def render(data):
    def e(value):
        return escape(str(value), quote=True)
    maximum = max(data['activity'].values(), default=1) or 1
    cells = ''.join(f'<span class="cell" style="opacity:{0.15 + .85 * count / maximum:.2f}" title="{e(day)}: {count} commits"></span>' for day, count in data['activity'].items())
    people = ''.join(f'<tr><td>{e(p["name"])}</td><td>{p["commits"]}</td></tr>' for p in data['contributors']) or '<tr><td colspan="2">No commits in this window</td></tr>'
    commits = ''.join(f'<li><code>{e(c["sha"][:8])}</code> {e(c["subject"])}<small>{e(c["author"])} · {e(c["date"][:10])}</small></li>' for c in data['recent'])
    signals = ''.join(f'<li><span>{"✓" if found else "○"}</span> {e(name.title())}</li>' for name, found in data['signals'].items())
    bars = ''.join(f'<div class="barrow"><span>{day}</span><div class="bar" style="width:{count / (max(data["weekdays"]) or 1) * 100:.1f}%"></div><b>{count}</b></div>' for day, count in zip(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], data['weekdays']))
    warning = '<p class="warning">Shallow clone: history may be incomplete.</p>' if data['shallow'] else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>DevPulse · {e(data['repository'])}</title><style>
:root{{color-scheme:dark;font-family:system-ui,sans-serif;background:#10131c;color:#ebedf8}}*{{box-sizing:border-box}}body{{margin:0}}main{{max-width:1120px;margin:auto;padding:48px 24px}}header{{border-bottom:1px solid #303747;padding-bottom:30px}}.brand{{color:#ac9bff;letter-spacing:.18em;font-size:12px;font-weight:800}}h1{{font-size:clamp(32px,6vw,60px);margin:12px 0}}p,small{{color:#9da9bf}}.metrics{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:28px 0}}.card{{background:#191f2d;border:1px solid #303747;border-radius:18px;padding:24px}}.number{{display:block;font-size:40px;font-weight:750;color:#d5ccff}}h2{{font-size:18px;margin:0 0 20px}}.heatmap{{display:flex;flex-wrap:wrap;gap:4px}}.cell{{width:13px;height:13px;background:#9d89ff;border-radius:3px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}}table{{width:100%;border-collapse:collapse}}td,th{{text-align:left;padding:12px 0;border-bottom:1px solid #303747}}th{{color:#9da9bf;font-size:12px}}ul{{list-style:none;padding:0;margin:0}}li{{padding:10px 0;overflow-wrap:anywhere}}small{{display:block;margin-top:5px}}code{{color:#b9aaff;font-size:12px}}.barrow{{display:grid;grid-template-columns:40px 1fr 30px;gap:10px;align-items:center;margin:13px 0;font-size:13px}}.bar{{background:linear-gradient(90deg,#8070ef,#b5a5ff);height:8px;border-radius:8px}}.warning{{color:#f1ca7a}}footer{{margin-top:30px;color:#9da9bf;font-size:12px}}@media(max-width:650px){{.grid{{grid-template-columns:1fr}}.metrics{{gap:8px}}.metrics .card{{padding:14px}}.number{{font-size:30px}}}}
</style></head><body><main><header><div class="brand">DEVPULSE / REPOSITORY INSIGHTS</div><h1>{e(data['repository'])}</h1><p>{e(data['start'])} — {e(data['end'])} · Local analysis. No uploads. No tracking.</p>{warning}</header><section class="metrics" aria-label="Summary"><div class="card"><span class="number">{data['commits']}</span>Commits</div><div class="card"><span class="number">{len(data['contributors'])}</span>Contributors</div><div class="card"><span class="number">{data['active_days']}</span>Active days</div></section><section class="card"><h2>Activity timeline</h2><div class="heatmap" role="img" aria-label="Daily commit activity; detailed counts available in JSON output">{cells}</div><p>Each square is one day, oldest first. Brighter means more commits.</p></section><div class="grid"><section class="card"><h2>Contributors</h2><table><thead><tr><th>Name</th><th>Commits</th></tr></thead><tbody>{people}</tbody></table></section><section class="card"><h2>Weekly rhythm</h2>{bars}</section><section class="card"><h2>Repository signals</h2><ul>{signals}</ul><p>Presence checks only; these do not measure code quality.</p></section><section class="card"><h2>Recent commits</h2><ul>{commits}</ul></section></div><footer>DevPulse · Author dates, all refs, mailmap identities. Activity is not a measure of individual productivity.</footer></main></body></html>'''
